final RateLimiter limiter = RateLimiter.create(100.0);   // 100 permits/s, smooth
if (limiter.tryAcquire()) {          // shed instead of queue
    handle(request);
} else {
    response.setStatus(429);
    response.setHeader("Retry-After", "1");
}
// alternative: limiter.acquire();  // blocks, spreading callers to the rate

