RateLimiterConfig cfg = RateLimiterConfig.custom()
    .limitRefreshPeriod(Duration.ofSeconds(1))
    .limitForPeriod(100)
    .timeoutDuration(Duration.ZERO)                 // fail fast over the limit
    .build();
RateLimiter limiter = RateLimiterRegistry.of(cfg).rateLimiter("api");
CheckedRunnable call = RateLimiter.decorateCheckedRunnable(limiter, service::handle);
try { call.run(); } catch (RequestNotPermitted e) { respond429(); }
